import{_ as e,o,c as n,a as i}from"./chunks/plugin-vue_export-helper.B1AaF8Z1.js";const h=JSON.parse('{"title":"Лучшие промышленные практики построения AI-агентов, 8 из 10","description":"","frontmatter":{"site":"pro","title":"Лучшие промышленные практики построения AI-агентов, 8 из 10","date":"2026-10-10T00:00:00.000Z","source":"https://t.me/jfyi_ps/101","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-10-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-8"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Лучшие промышленные практики построения AI-агентов, 8 из 10"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-10-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-8"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Лучшие промышленные практики построения AI-агентов, 8 из 10"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Лучшие промышленные практики построения AI-агентов, 8 из 10\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-10-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-8\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-10\\"}"]]},"headers":[],"relativePath":"posts/2026-10-10-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-8.md","filePath":"posts/2026-10-10-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-8.md"}'),r={name:"posts/2026-10-10-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-8.md"};function a(s,t,p,l,g,c){return o(),n("div",null,[...t[0]||(t[0]=[i("<p>Выжимка из книги Ли Боцзе «Глубокое понимание AI Agent: принципы проектирования и инженерная практика» (Pine AI, v2.0, 2026). ** 8. Постобучение модели**</p><p>Три слоя решают разное: Mid-training (недостающие знания/навыки) → SFT (протокол формата/стиля) → RL (обобщение/поиск стратегий). Диагностируй ПЕРЕД выбором: pass@1 и pass@k. pass@k≈0 → Mid-training; растёт, но формат не парсится → SFT; есть разброс наград → RL. RL на нулевых rollout тратит бюджет впустую.</p><p>Mid-training ≠ набивание знаний через QA-пары; для часто меняющихся фактов — RAG, не параметры. «Двойное воспроизведение»: общие данные + старые задачи в поднятой длине. «Сначала SFT» — условно, не универсально.</p><p><strong>SFT:</strong> математически next-token predict + loss masking на ответе. Хватает тысяч примеров — чистота важнее объёма. 3 источника: демо экспертов, дистилляция учителя, отбраковочное сэмплирование (RFT). LoRA — дефолт (все основные матрицы, особенно MLP; lr ×10 выше; ранг 64-256 SFT / 8-32 RL). Дистилляция промпта — для стабильного продукта, не исследования. Синтетика извлекает структуру задачи из логов (не пересказ). Неудачные траектории — в DPO-пары, не как демо.</p><p><strong>RL:</strong> узкое место — среда и данные, не алгоритм. Если среду не построить — симулируй моделью, но знание симулятора = потолок обучения, следи за reward hacking через дыры симулятора. Train/eval не делят один набор задач. Маскируй токены среды в градиенте. Сверяй log-probability sampler/trainer перед обновлением.</p><p><strong>Награда:</strong> RLVR надёжнее оценки моделью. Reward hacking (обход правила) ≠ reward seeking (подстройка под догадку о проверяющем). «Готово» решают скрытые тесты, не заявление модели. Граничный+удерживающий набор вместе. Начинай с награды за результат, добавляй процессные сигналы только для проверяемых событий. RLVP: раздели результат+сигнал пути, сохраняй награду за результат.</p><p>On-Policy Distillation (ученик сэмплирует, учитель даёт полное распределение) — на порядок плотнее сигнал, чем бинарная награда; нужен сильный учитель. Без него — самодистилляция (OPSD).</p><p>Bad case → постобучение: атрибуция → пары предпочтений вокруг границы → LoRA на малой доле от общих данных → оценка на граничном И удерживающем наборах.</p><p>Ловушки: не используй постобучение для фактов, не вводи RL до стабилизации формата, проектируй награду против взлома, не экономь на достоверности симуляции, следи за переобучением отдельно от training loss, закладывай стоимость RL (×10-100 к SFT) реалистично.</p><p>Добавлю от себя: в данных для обучения не должно быть перекосов - модель переобучится в одну сторону. Также, набор не должен быть 50/50 в разные стороны - это приводит к зацикливанию.</p><p>Продолжение следует...</p>",11)])])}const d=e(r,[["render",a]]);export{h as __pageData,d as default};
